create table if not exists site_content(id text primary key, data jsonb not null default '{}', updated_at timestamptz default now());
create table if not exists site_history(id bigserial primary key, data jsonb not null, created_at timestamptz default now());
create table if not exists admins(user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists bookings(id bigserial primary key, created_at timestamptz default now(), name text, phone text, email text, address text, service text, date text, time text, total text, status text default 'Pending', cleaner text default 'Unassigned');
create table if not exists quotes(id bigserial primary key, created_at timestamptz default now(), name text, email text, message text);
alter table site_content enable row level security; alter table site_history enable row level security; alter table admins enable row level security; alter table bookings enable row level security; alter table quotes enable row level security;
create or replace function public.is_admin() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()) $$;
create policy "own admin row" on admins for select using (user_id=auth.uid());
create policy "public reads live" on site_content for select using (id='live');
create policy "admin all content" on site_content for all using (is_admin()) with check (is_admin());
create policy "admin all history" on site_history for all using (is_admin()) with check (is_admin());
create policy "public can book" on bookings for insert to anon, authenticated with check (char_length(name)<200 and char_length(coalesce(address,''))<400);
create policy "admin all bookings" on bookings for all using (is_admin()) with check (is_admin());
create policy "public can quote" on quotes for insert to anon, authenticated with check (char_length(coalesce(message,''))<3000);
create policy "admin all quotes" on quotes for all using (is_admin()) with check (is_admin());
insert into storage.buckets(id,name,public) values('media','media',true) on conflict (id) do nothing;
create policy "public reads media" on storage.objects for select using (bucket_id='media');
create policy "admin writes media" on storage.objects for insert with check (bucket_id='media' and public.is_admin());
create policy "admin updates media" on storage.objects for update using (bucket_id='media' and public.is_admin());
create policy "admin deletes media" on storage.objects for delete using (bucket_id='media' and public.is_admin());
